		`{"type":"event","key":"k","time":100,"value":9007199254740993}`, // 2^53+1
		`{"type":"event","key":"k","time":700,"value":9007199254740993}`, // shared by both windows
		`{"type":"watermark","time":1600}`,
	}, "\n")
	stdout, stderr, err := runSliding(t, input, 1000, 600)
