		`{"key":"k","start":0,"end":1000,"count":2,"sum":18014398509481986}`, // 2*(2^53+1)
		`{"key":"k","start":600,"end":1600,"count":1,"sum":9007199254740993}`,
		``,
	}, "\n")
	if stdout != want {
		t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
	}
}

